def is_multiply_prime(a):
    """Determine if the given number is the product of exactly three prime numbers."""
    if a < 2:
        return False

    # Helper function to check if a number is prime
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    # Generate all primes less than 100
    primes = [p for p in range(2, 100) if is_prime(p)]

    # Check if `a` can be expressed as the product of exactly three primes
    from itertools import combinations_with_replacement
    for p1, p2, p3 in combinations_with_replacement(primes, 3):
        if p1 * p2 * p3 == a:
            return True
    return False
